// ============================================================ forastero/a: patria, estatus legal (meteco / ciudadanía), hospitalidad, cuaderno de comparaciones y regreso (nóstos)
function fxz(){if(!state.fx||typeof state.fx!=='object')state.fx={};const f=state.fx;f.tes=f.tes||{};f.cuad=f.cuad||{};f.coins=f.coins||{};if(!f.st)f.st='xenos';if(!f.d0)f.d0=state.day||1;return f;}
const ORIG={
 atenas:[
  {id:'mileto',n:'Mileto, en Jonia',de:'de Mileto',gm:'milesio',gf:'milesia',pn:'Arquéstrato',pt:'Ateniense, próxeno de los milesios',look:{chiton:'#e6dcc4',himation:'#3f5a6a',beard:true,hair:'#5a4a3a'},
   pi:'¡Un milesio! Soy Arquéstrato, ateniense. Tu ciudad me nombró su próxeno: cuando un milesio tiene problemas en Atenas, viene a mi casa. Es un honor y, a veces, un trabajo.',
   tp:[['¿Qué pasa ahora con Mileto?','Malas noticias de tu tierra: la paz del Rey de este año entrega al Gran Rey de Persia todas las ciudades griegas de Asia. Mileto vuelve a pagar tributo a un sátrapa. Los atenienses, que tanto hablan de libertad, la han firmado. Lo siento, amigo.'],['¿Qué saben de Mileto los atenienses?','Que fue la ciudad más rica de Jonia y la madre de colonias en todo el mar Negro. Que allí nacieron Tales y Anaximandro, los primeros que buscaron el origen de todo sin hablar de dioses. Y que vuestro Hipódamo trazó las calles rectas del Pireo. Cuando los persas arrasaron Mileto en el 494, el poeta Frínico hizo una tragedia sobre ello y los atenienses lloraron tanto que le pusieron una multa.'],['¿Cómo me tratarán aquí?','Bien, mientras pagues. Pero oirás el refrán: «Hace tiempo los milesios fueron valientes», que Aristófanes ha vuelto a poner en boca de todos. Lo dicen para burlarse de que os habéis vuelto ricos y blandos. Tú sonríe.']],
   bark:['¿Milesio? «Hace tiempo los milesios fueron valientes»… ¡Es broma, es broma!','Los de Mileto tejéis la lana más fina del mundo. ¿Me vendes un manto?'],
   react:'Al oír «de Mileto», sonríe: «Jonio. Se nota en cómo alargas las vocales».'},
  {id:'siracusa',n:'Siracusa, en Sicilia',de:'de Siracusa',gm:'siracusano',gf:'siracusana',pn:'Leóstenes',pt:'Ateniense, próxeno de los siracusanos',look:{chiton:'#e9dfcb',himation:'#7a3a2a',beard:true,hair:'#3a2a1e'},
   pi:'Siracusa… Soy Leóstenes, próxeno de tu ciudad. Te advierto que en Atenas tu patria despierta recuerdos amargos.',
   tp:[['¿Por qué recuerdos amargos?','Hace veintisiete años, en el 413, nuestra gran expedición murió ante vuestras murallas. Miles de atenienses acabaron en vuestras canteras, bajo el sol, con un cuartillo de agua al día. Dicen que algunos se salvaron recitando versos de Eurípides, que en Sicilia adoráis: los siracusanos liberaban a quien supiera sus coros.'],['¿Y Dionisio?','Vuestro tirano Dionisio es hoy el hombre más poderoso de Occidente. En los últimos Juegos Olímpicos, el orador Lisias, que es de familia siracusana, pidió a los griegos que se unieran contra él, y la gente atacó sus tiendas de lujo. Aquí no lo quiere nadie. Si te preguntan, di que eres de Siracusa, no de Dionisio.'],['¿Qué más une a Atenas y Siracusa?','El teatro. Esquilo estrenó obras en Siracusa, y vosotros tenéis vuestra propia comedia, la de Epicarmo. Y los filósofos: dicen que Platón ha estado hace poco en la corte de Dionisio y ha salido mal parado. Las ideas viajan por mar, como el trigo.']],
   bark:['¿Siracusano? Mi abuelo murió en vuestras canteras. Bueno, tú no tienes la culpa.','En Siracusa sí que se come bien, dicen. Aquí, cebada y aceitunas.'],
   react:'Al oír «de Siracusa», se le borra un momento la sonrisa: la expedición del 413 aún duele en Atenas.'},
  {id:'tebas',n:'Tebas, en Beocia',de:'de Tebas',gm:'tebano',gf:'tebana',pn:'Teógenes',pt:'Ateniense, próxeno de los tebanos',look:{chiton:'#efe2c8',himation:'#4f6a3a',beard:true,hair:'#3b2a1e'},
   pi:'¡Un tebano, aquí! Soy Teógenes. Atenas os debe mucho, aunque aquí os llamen cerdos beocios. Yo os aprecio.',
   tp:[['¿Por qué nos debe tanto Atenas?','Cuando los Treinta Tiranos gobernaban aquí, en el 404, Tebas acogió a los demócratas desterrados, aunque Esparta lo prohibía. Desde Tebas salió Trasibulo a liberar Atenas. Él mismo dedicó en vuestro Heracleo dos estatuas de Alcámenes como agradecimiento.'],['¿Por qué nos llaman cerdos beocios?','Porque los atenienses se creen los más listos de Grecia y piensan que los beocios solo saben comer: vuestra llanura es la más fértil y vuestras anguilas del Copais, las mejores. Píndaro, que era tebano, ya se quejaba del insulto hace cien años. Contesta con Píndaro y se callarán.'],['¿Cómo está Tebas ahora?','Mal. La paz del Rey os ha obligado a disolver la Liga Beocia y Esparta vigila. Los vuestros están divididos entre los de Ismenias y los de Leontíadas. Si tienes familia allí, escríbeles que tengan cuidado.']],
   bark:['¡Eh, beocio! ¿Has traído anguilas del Copais?','Los tebanos habláis como si tuvierais la boca llena. Normal, siempre estáis comiendo.'],
   react:'Al oír tu acento beocio, se le escapa una sonrisa burlona, aunque enseguida te da la mano.'},
  {id:'corinto',n:'Corinto',de:'de Corinto',gm:'corintio',gf:'corintia',pn:'Eufileto',pt:'Ateniense, próxeno de los corintios',look:{chiton:'#e9dfcb',himation:'#7a2a3a',beard:true,hair:'#3b2a1e'},
   pi:'Corintio, ¿eh? Soy Eufileto, vuestro próxeno. Hace un año éramos aliados contra Esparta; hace veinte, enemigos. Con Corinto nunca se sabe.',
   tp:[['¿Amigos o enemigos?','En la guerra del Peloponeso, Corinto fue el peor enemigo de Atenas: vuestros embajadores convencieron a Esparta de declararnos la guerra, como cuenta Tucídides. Luego, en la guerra de Corinto, luchamos juntos. Ahora, con la paz, vuelven a vuestra ciudad los amigos de Esparta. Aquí os miran con cariño y con desconfianza a la vez.'],['¿Qué saben de Corinto los atenienses?','Que sois ricos, que tenéis dos puertos y que vuestro diolkos os llena las arcas. Que vuestros bronces y vuestras vasijas se vendían en todo el mar, aunque ahora la cerámica ática os ha ganado. Y el refrán: «No todos pueden ir a Corinto», porque allí todo es caro.'],['¿Me será útil ser corintio?','Para el comercio, mucho: los mercaderes del Pireo confían en los corintios. Para la política, nada: un forastero no vota. Pero eso ya lo sabías.']],
   bark:['«No todos pueden ir a Corinto». ¡Y tú vienes de allí! Algo tendrás ahorrado.','Corintio… Vuestro diolkos se queda con la mitad de las ganancias de todo el mar.'],
   react:'Al oír «de Corinto», asiente despacio, como quien recuerda una guerra.'},
  {id:'tracia',n:'Tracia',de:'de Tracia',gm:'tracio',gf:'tracia',barb:true,pn:'Bitis',pt:'Tracio, de la cofradía de Bendis en el Pireo',look:{chiton:'#b7a27c',himation:'#8a3f2f',beard:true,hair:'#6b4a2a',petasos:'head'},
   pi:'¡Paisano! Soy Bitis. En Atenas hay muchos tracios, pero casi todos son esclavos: en las minas, en los barcos, en las casas. Tú eres libre. Que no se te olvide, y que no se les olvide a ellos.',
   tp:[['¿Cómo ven aquí a los tracios?','Para los griegos somos bárbaros: no hablamos griego en casa y nos tatuamos la piel. Los esclavos de las minas del Laurio son muchos tracios. Pero los atenienses también nos admiran: nuestros peltastas, con su escudo ligero en forma de media luna, han enseñado a Ifícrates a vencer a los espartanos.'],['¿Qué es la cofradía de Bendis?','Bendis es nuestra diosa cazadora, como su Ártemis. Hace más de cuarenta años, los atenienses aceptaron su culto, y en el Pireo celebramos las Bendidias con una procesión de tracios y otra de atenienses y una carrera de antorchas a caballo, de noche. Sócrates bajó a verla una vez, y Platón cuenta que allí empezó una larga conversación sobre la justicia.'],['¿Quién responderá por mí?','Para quedarte aquí necesitas un ciudadano que responda por ti, un prostátes. Yo no puedo: soy meteco. Pero en la cofradía hay atenienses, y uno de ellos me debe un favor. Considéralo hecho.']],
   bark:['¿Tracio y libre? Hablas griego mejor que mi cuñado.','Los tracios beben el vino sin mezclar, dicen. ¿Es verdad?'],
   react:'Al oír «de Tracia», te mira de arriba abajo: no esperaba un tracio libre preguntando cosas.'},
  {id:'naucratis',n:'Náucratis, en Egipto',de:'de Náucratis',gm:'naucratita',gf:'naucratita',pn:'Hermón',pt:'Mercader de Náucratis, meteco del Pireo',look:{chiton:'#efe8da',himation:'#c9a24a',beard:true,hair:'#2a1a12'},
   pi:'¡De Náucratis! Soy Hermón: vendo papiro, lino y natrón en el Pireo. Somos griegos de Egipto, y aquí nos miran como si viniéramos de la luna.',
   tp:[['¿Qué es Náucratis para los atenienses?','La ciudad griega del delta del Nilo, donde los faraones dejaron comerciar a los griegos hace casi dos siglos. Por allí sale el trigo de Egipto y entra el aceite y la plata de Grecia. Heródoto y Solón pasaron por ella. Los atenienses creen que todo lo de Egipto es antiquísimo y misterioso. Tienen razón a medias.'],['¿Cómo está Egipto ahora?','Libre de los persas desde hace casi veinte años. El faraón Hakor se ha aliado con Evágoras de Chipre y con Atenas contra el Gran Rey. Pero con la paz del Rey, Atenas ha abandonado a sus amigos. Si Persia ataca Egipto, estaremos solos.'],['¿Quién responderá por mí?','Yo soy meteco: no puedo ser tu prostátes. Pero mi socio en el Pireo es ateniense y responderá por ti. Con el comercio, todo se arregla.']],
   bark:['¿De Egipto? Heródoto dice que allí las mujeres van al mercado y los hombres tejen en casa.','¿Es verdad que en Egipto embalsaman a los gatos?'],
   react:'Al oír «de Egipto», abre mucho los ojos: «¿Has visto las pirámides?».'}
 ],
 roma:[
  {id:'malaca',n:'Malaca, en la Bética',de:'de Malaca',gm:'malacitano',gf:'malacitana',pn:'Lucio Fabio Severo',pt:'De la estación de los municipios de la Bética',look:{chiton:'#e9dfcb',himation:'#7a5a3a',hair:'#2b1f17'},
   pi:'¡Salve, paisano! Lucio Fabio, de Malaca. Aquí, junto al Templo de la Paz, las ciudades de provincias tienen sus estaciones, sus oficinas: aquí llegan nuestros embajadores, nuestras cartas y nuestras quejas.',
   tp:[['¿Qué noticias hay de Malaca?','¡Las mejores! El emperador Vespasiano concedió el derecho latino a toda Hispania, como cuenta Plinio. Malaca, que era una ciudad de peregrinos, de extranjeros sin derechos romanos, se está convirtiendo en municipio, con sus magistrados y su ley grabada en bronce. Y quien sea magistrado de un municipio latino se hace ciudadano romano, con su mujer, sus padres y sus hijos.'],['¿Cómo puedo hacerme ciudadano?','Hay varios caminos. Servir veinticinco años en las tropas auxiliares: al licenciarte te dan la ciudadanía en una tablilla de bronce. Que un ciudadano te libere, si eres esclavo. Que el emperador te la conceda, si alguien importante lo pide por ti. O el nuestro: ser magistrado en un municipio latino. Ve a Corduba y busca a Lucio Valerio Firmo, duunviro de Malaca. Él te explicará.'],['¿Por qué no puedo llevar toga?','Porque la toga es el traje de los ciudadanos romanos. El emperador Claudio la prohibió a los peregrinos, como cuenta Suetonio. Tú puedes llevar túnica y manto, como cualquiera. Pero el día que seas ciudadano, ¡toga de lana blanca, y que te vea todo el Foro!']],
   bark:['¿Hispano? Aquí todo lo bueno viene de Hispania: el aceite, el garum… y los poetas.','Malaca… ¿Eso no era fenicio?'],
   react:'Al oír «de Malaca», asiente: «Hispano. Como Séneca, como Marcial…».'},
  {id:'massilia',n:'Massilia, en la Galia',de:'de Massilia',gm:'masaliota',gf:'masaliota',pn:'Apolonio',pt:'De la estación de los masaliotas',look:{chiton:'#efe8da',himation:'#2f4c86',beard:true,hair:'#5a4a3a'},
   pi:'Χαῖρε… ¡perdón, salve! Apolonio, de Massilia. En casa hablamos griego; aquí, latín con acento. Massilia es una ciudad libre y aliada de Roma: no somos romanos, pero tampoco súbditos.',
   tp:[['¿Qué significa ser ciudad aliada?','Que Massilia tiene sus propias leyes, sus seiscientos timucos y su moneda. Fuimos aliados fieles de Roma durante siglos, hasta que apoyamos a Pompeyo y César nos quitó casi todo el territorio. Seguimos siendo libres, pero más pequeños.'],['¿Qué piensan los romanos de nosotros?','Que somos sabios y austeros. Agrícola, el que gobierna Britania, estudió en Massilia; su madre lo envió allí porque es la escuela de la Galia, griega y sobria. Tácito, su yerno, lo contará algún día.'],['¿Por qué no somos ciudadanos?','Porque un masaliota es ciudadano de Massilia. Hay quien recibe además la ciudadanía romana por sus servicios, y entonces tiene dos patrias. Si la quieres, pregunta en la estación de los béticos por el derecho latino: allí hay un camino abierto.']],
   bark:['¿Masaliota? Griego, entonces. Ten cuidado: los romanos dicen «grieguecillo» con desprecio.','En Massilia los jóvenes estudian filosofía en vez de beber. ¡Qué aburrimiento!'],
   react:'Al oír «de Massilia», dice: «Griega y austera. Allí estudió Agrícola, ¿no?».'},
  {id:'alejandria',n:'Alejandría, en Egipto',de:'de Alejandría',gm:'alejandrino',gf:'alejandrina',pn:'Teón',pt:'Armador alejandrino de la flota del trigo',look:{chiton:'#efe8da',himation:'#c9a24a',hair:'#2a1a12'},
   pi:'¡Un alejandrino! Soy Teón. Mis barcos traen el trigo de Egipto a Ostia: sin nosotros, Roma pasaría hambre en un mes. Y aun así nos miran por encima del hombro.',
   tp:[['¿Por qué nos miran así?','Egipto no es una provincia cualquiera: es propiedad del emperador, y ningún senador puede entrar sin su permiso. A los alejandrinos nos tienen por listos, burlones y alborotadores: insultamos a los gobernadores con canciones y hacemos motines en el hipódromo. Algo de razón tienen.'],['¿Qué tiene Alejandría que no tenga Roma?','El Museo y la Biblioteca, con cientos de miles de rollos; el Faro, una de las maravillas; la tumba de Alejandro. Aquí vienen médicos, astrónomos y gramáticos a estudiar. Roma es más grande, pero Alejandría es más sabia.'],['¿Puedo hacerme ciudadano?','Para un egipcio es casi imposible: antes tiene que ser ciudadano de Alejandría. Nosotros los alejandrinos lo tenemos más fácil, pero hace falta un patrono importante que lo pida al emperador. O el camino de Hispania, si te apetece cambiar de patria.']],
   bark:['¿Alejandrino? Sin vuestro trigo, aquí no come nadie. Gracias, supongo.','En Alejandría, dicen, hasta los barqueros saben de astronomía.'],
   react:'Al oír «de Alejandría», murmura: «Trigo, papiro y mala lengua».'},
  {id:'atenas_r',n:'Atenas, en Acaya',de:'de Atenas',gm:'ateniense',gf:'ateniense',pn:'Calias',pt:'Ateniense, maestro de griego en Roma',look:{chiton:'#efe6d4',himation:'#4f6a7d',beard:true,hair:'#8d8a85'},
   pi:'Χαῖρε, paisano. Calias, ateniense. Enseño griego a los hijos de los senadores: aquí todo romano bien educado habla griego, aunque luego nos llamen «grieguecillos».',
   tp:[['¿Qué es hoy Atenas para Roma?','Una ciudad libre y aliada, pequeña y venerable: la universidad del mundo. Los jóvenes romanos ricos van a estudiar filosofía y retórica a la Academia y al Liceo. Cicerón estudió allí. Pero ya no manda en nada.'],['¿Y la libertad de Grecia?','Nerón, que adoraba Grecia, proclamó en Corinto, hace trece años, la libertad de toda Acaya. Vespasiano la anuló: dijo que los griegos habían olvidado cómo ser libres. Suetonio lo contará. Volvemos a ser provincia y a pagar tributo.'],['¿Por qué nos desprecian si nos imitan?','Porque se sienten herederos y a la vez superiores: conquistaron Grecia, pero, como dijo Horacio, «la Grecia conquistada conquistó a su fiero vencedor». Leen a Homero, copian nuestras estatuas, contratan médicos y maestros griegos… y se burlan de nosotros en la misma frase.']],
   bark:['¿Ateniense? «Grieguecillo», diría mi suegro. Yo te respeto.','Los atenienses sabéis hablar mucho. Los romanos, mandar.'],
   react:'Al oír «de Atenas», dice en griego, con mal acento: «¡Khaîre!». Quiere impresionarte.'},
  {id:'britania',n:'Londinium, en Britania',de:'de Britania',gm:'britano',gf:'britana',pn:'Verecundo',pt:'Britano, mercader de lana y perros de caza',look:{chiton:'#b7a27c',himation:'#3f5a3a',hair:'#8a5a2a',beard:true},
   pi:'¡Alguien de la isla! Soy Verecundo, de Londinium. Vendo mantos de lana y perros de caza. En Roma nos miran como a bichos raros: llegamos del fin del mundo.',
   tp:[['¿Qué saben de Britania los romanos?','Que César cruzó el Océano y volvió deprisa, que Claudio nos conquistó hace treinta y siete años y que la reina Boudica quemó Londinium hace veinte. Ahora el gobernador Agrícola avanza hacia el norte, contra los caledonios. Aquí lo celebran como si fuéramos fieras.'],['¿Por qué se ríen de nosotros?','Por los calzones, las bracae: aquí los consideran ropa de bárbaros. Por las historias de César, que dice que nos pintamos de azul con hierba pastel. Y por el clima: piensan que en Britania llueve siempre. Eso, la verdad, es cierto.'],['¿Puedo hacerme ciudadano?','Muchos britanos sirven en las tropas auxiliares y, tras veinticinco años, reciben la ciudadanía. Otros la consiguen por un patrono. Agrícola, dicen, quiere que los hijos de los jefes aprendan latín y lleven toga. Si quieres un atajo, pregunta en la estación de los hispanos.']],
   bark:['¿Britano? ¿Es verdad que os pintáis de azul?','Del fin del mundo… ¿Y allí hay sol alguna vez?'],
   react:'Al oír «de Britania», pone los ojos como platos: «¡Del otro lado del Océano!».'},
  {id:'lepcis',n:'Lepcis Magna, en África',de:'de Lepcis Magna',gm:'lepcitano',gf:'lepcitana',pn:'Iddibal',pt:'Lepcitano, comerciante de aceite',look:{chiton:'#e9dfcb',himation:'#7a2a5e',hair:'#1f1610',beard:true},
   pi:'¡Paisano! Iddibal, de Lepcis. En casa hablamos púnico, la lengua de Cartago; en el foro, latín. Nuestras inscripciones se escriben en las dos lenguas.',
   tp:[['¿Cómo es Lepcis?','Una vieja ciudad fenicia en la costa de África, rica en aceite. Hace ochenta años, un noble lepcitano, Annóbal Tapapio Rufo, regaló a la ciudad un teatro, y lo dejó escrito en latín y en púnico. Vespasiano la acaba de convertir en municipio: sus magistrados se hacen ciudadanos romanos.'],['¿Qué piensan aquí de los africanos?','Que somos descendientes de Aníbal, el enemigo de Roma. En las comedias de Plauto, el cartaginés habla una lengua rara y lleva pendientes. Pero los romanos compran nuestro aceite y nuestras fieras para el anfiteatro. Algún día, ya verás, un africano será emperador.'],['¿Y la ciudadanía?','En Lepcis, la consiguen los que son magistrados del municipio. Pero tú estás en Roma. Pregunta en la estación de los béticos por el derecho latino de Hispania: allí también vale el camino del municipio.']],
   bark:['¿Africano? Vuestro aceite es más fuerte que el de Hispania. Para las lámparas, digo.','¿Hablas púnico? Dime algo. ¡Como en la comedia de Plauto!'],
   react:'Al oír «de Lepcis», dice: «Africano… ¿Hablas la lengua de Aníbal?».'}
 ]};
function origen(){const p=pjz();const L=ORIG[MODE]||[];return p&&p.o&&L.find(o=>o.id===p.o)||null;}
const fxG=(m,f)=>pjFem()?f:m;
const fxEsCiu=()=>MODE==='roma'&&!!(state&&state.fx&&state.fx.ciu);
function fxNombre(){const p=pjz();if(!p)return'';return fxEsCiu()?(p.g==='f'?'Flavia ':'Tito Flavio ')+p.name:p.name;}
// el paisano: un personaje cuyo nombre y conversación dependen de tu patria
const PAISANO={id:'paisano',glyph:'Π',cat:'Sociedad',get where(){return MODE==='roma'?'En las estaciones de los municipios, junto al Templo de la Paz':'En el Ágora, cerca de Lisias';},
 get name(){const o=origen();return o?o.pn:(MODE==='roma'?'Un funcionario de las estaciones':'Un próxeno');},
 get title(){const o=origen();return o?o.pt:(MODE==='roma'?'Estaciones de los municipios, junto al Templo de la Paz':'Representante de los forasteros');},
 get look(){const o=origen();return o?o.look:{chiton:'#e9dfcb',himation:'#5a5a6a',beard:true,hair:'#3b2a1e'};},
 get lesson(){return MODE==='roma'?'Peregrinos y ciudadanos':'Forasteros y metecos';},
 get summary(){return MODE==='roma'?'En el Imperio del 80 d.C. la mayoría de los habitantes libres eran peregrinos, ciudadanos de su propia ciudad pero no de Roma. La ciudadanía romana daba derechos (casarse según el derecho romano, testar, apelar al emperador, llevar toga) y se obtenía por nacimiento, por liberación de un amo ciudadano, tras veinticinco años en las tropas auxiliares, por concesión del emperador o, en las ciudades de derecho latino, siendo magistrado local. Vespasiano concedió el derecho latino a toda Hispania hacia el 73-74 (Plinio, Historia natural III 30), y las leyes de sus municipios, grabadas en bronce, se han encontrado en Malaca, Salpensa e Irni.':'En la Atenas del 386 a.C., un forastero (xénos) que se quedaba a vivir en la ciudad tenía que inscribirse como meteco: necesitaba un ciudadano que respondiera por él (el prostátes) y pagaba un impuesto anual, el metoíkion, de doce dracmas los hombres y seis las mujeres que vivían por su cuenta. Los metecos no votaban, no podían tener tierra ni casa sin un permiso especial (la énktesis) y servían en el ejército. Las ciudades nombraban próxenos: ciudadanos de otra polis que cuidaban de sus paisanos. Quien vivía en Atenas sin inscribirse podía ser denunciado y vendido como esclavo.';},
 get intro(){const o=origen();if(!o)return MODE==='roma'?'Salve. Aquí, junto al Templo de la Paz, cada ciudad de provincias tiene su oficina. Dime de dónde eres y te busco a tu gente. (Elige tu patria en el Diario, pestaña «Forastero».)':'Bienvenido a Atenas. Cada ciudad nombra aquí a un próxeno que cuida de sus paisanos. Dime de dónde eres. (Elige tu patria en el Diario, pestaña «Forastero».)';return o.pi;},
 get topics(){const o=origen();return o?o.tp:[[MODE==='roma'?'¿Qué es una estación?':'¿Qué es un próxeno?',MODE==='roma'?'Las ciudades de las provincias tienen aquí, junto al Templo de la Paz, sus «estaciones»: oficinas donde se alojan sus embajadores y donde los paisanos se ayudan. Plinio habla de ellas.':'Un ciudadano de Atenas al que otra ciudad nombra su representante. Si un forastero de esa ciudad tiene problemas, acude a él. Es un honor que se graba en una estela.']];},
 quiz:{get q(){return MODE==='roma'?'¿Qué concedió Vespasiano a toda Hispania?':'¿Qué necesitaba un forastero para inscribirse como meteco en Atenas?';},
  get a(){return MODE==='roma'?['El derecho latino: los magistrados de sus municipios se hacían ciudadanos romanos','La ciudadanía romana a todos sus habitantes','La exención de todos los impuestos']:['Un ciudadano que respondiera por él, el prostátes, y pagar el metoíkion','Comprar una casa en el Ática','Hablar en la Asamblea y ganar una votación'];},
  get ko(){return MODE==='roma'?'No. Vespasiano dio a Hispania el derecho latino: los que eran magistrados en sus municipios se hacían ciudadanos romanos.':'No. Hacía falta un prostátes, un ciudadano que respondiera por él, y pagar cada año el metoíkion.';}}};
NPCS.push(PAISANO);
const DEMARCO={id:'demarco',name:'Nausícrates',title:'Demarco de Mélite',glyph:'Δ',look:{chiton:'#e8dfcc',himation:'#6a4a2a',beard:true,hair:'#8d8a85',staff:true},
 cat:'Política',lesson:'Los demos y los metecos',where:'En el Ágora, junto a la mesa de los registros',
 summary:'El Ática estaba dividida en unos 139 demos, aldeas o barrios, cada uno con su asamblea y su demarco. Los ciudadanos se inscribían en el demo de su padre al cumplir dieciocho años; los metecos se registraban como «residentes en» un demo (Mélite, el Pireo…). El metoíkion se pagaba cada año. Los metecos ricos pagaban también impuestos extraordinarios y liturgias, servían como hoplitas y desfilaban en las Panateneas llevando bandejas de ofrendas. Sus pleitos los llevaba el polemarco.',
 intro:'Soy Nausícrates, demarco de Mélite este año: llevo las cuentas del demo, convoco su asamblea y, entre otras cosas, anoto a los metecos que viven aquí. Si eres forastero y te quedas, tarde o temprano tendrás que pasar por mi mesa.',
 topics:[['¿Qué es un demo?','Un barrio o una aldea del Ática. Clístenes, hace más de cien años, organizó Atenas en demos: cada ciudadano lleva en su nombre el de su demo, «Fulano de Mélite», «Mengano de Acarnas». Es su identidad. Tú, si te inscribes, serás «residente en Mélite».'],['¿Qué obligaciones tiene un meteco?','Pagar el metoíkion: doce dracmas al año un hombre, seis una mujer que vive por su cuenta. Si eres rico, pagar además impuestos de guerra y algunas liturgias. Servir en el ejército si te llaman. Y en las Panateneas, los metecos desfilan con túnicas rojas llevando bandejas de pasteles y panales. Es un honor, aunque no lo parezca.'],['¿Y qué derechos?','Puedes trabajar, comerciar, casarte con quien quieras de tu condición, rezar a tus dioses y acudir a los tribunales, a través del polemarco. No puedes votar, ni ser jurado, ni tener tierra o casa sin un decreto especial. Lisias, el orador, es meteco: el hombre que mejor escribe de Atenas no puede votar en ella.']],
 quiz:{q:'¿Qué no podía hacer un meteco en la Atenas del siglo IV a.C.?',a:['Votar en la Asamblea ni tener tierra sin un decreto especial','Trabajar como artesano o banquero','Rezar a sus propios dioses'],ko:'No. Los metecos trabajaban, comerciaban y tenían sus cultos, pero no votaban ni podían tener tierra o casa sin un decreto de la Asamblea.'}};
NPCS.push(DEMARCO);
LESSONS.paisano={get title(){return PAISANO.lesson;},cat:'Sociedad',get summary(){return PAISANO.summary;},where:'En el Ágora, cerca de Lisias',get who(){return PAISANO.name;},fict:true};
LESSONS.demarco={title:DEMARCO.lesson,cat:DEMARCO.cat,summary:DEMARCO.summary,where:DEMARCO.where,who:DEMARCO.name,fict:true};
Object.defineProperty(NPC_POS,'paisano',{enumerable:true,configurable:true,get(){return MODE==='roma'?[104,-138,Math.PI]:[...AL(-80,-56),Math.PI/2];}});
Object.defineProperty(NPC_POS,'demarco',{enumerable:true,configurable:true,get(){return[...AL(-66,-80),Math.PI/2];}});
Object.assign(SRC,{paisano:{a:['Jenofonte, Poros 2 (los metecos)','Aristóteles, Constitución de los atenienses 58 (el polemarco)','Platón, República 327a (las Bendidias)','Tucídides VII 87 (las canteras de Siracusa)'],m:['D. Whitehead, The Ideology of the Athenian Metic (1977)'],n:['Los próxenos y los paisanos son inventados.']},
 demarco:{a:['Aristóteles, Constitución de los atenienses 21 y 42 (demos e inscripción)','Jenofonte, Poros 2','Lisias XII (un meteco ante los Treinta)'],m:['D. Whitehead, The Demes of Attica (1986)'],n:['Nausícrates es inventado.']}});
// modo Roma: el paisano en las estaciones y el duunviro de Malaca en Corduba
ROMA_NPCS.push(PAISANO);
const MALACITANO={id:'malacitano',name:'Lucio Valerio Firmo',title:'Duunviro de Malaca, de visita en Corduba',glyph:'L',look:{toga:true,chiton:'#efe9dc',himation:'#f3eee2',hair:'#5b4532'},
 cat:'Política',lesson:'El derecho latino y los municipios flavios',where:'En Corduba, junto al foro',
 summary:'Hacia el 73-74 d.C., Vespasiano concedió el derecho latino a toda Hispania. Las ciudades de peregrinos se convirtieron en municipios latinos, con decuriones, dos duunviros, dos ediles y dos cuestores elegidos cada año. Al terminar su cargo, los magistrados recibían la ciudadanía romana para ellos, sus padres, sus esposas y sus hijos, y tomaban el nombre de familia del emperador: Flavio. Las leyes de estos municipios se grababan en tablas de bronce: se han encontrado las de Malaca y Salpensa (1851) y la de Irni (1981).',
 intro:'Salve. Lucio Valerio Firmo, duunviro de Malaca: he venido a Corduba a ver al gobernador por los límites de nuestro territorio. Desde que el divino Vespasiano nos dio el derecho latino, en Malaca no hay día sin papeleo… ni sin alegría.',
 topics:[['¿Qué es el derecho latino?','Un escalón entre el peregrino y el ciudadano romano. Una ciudad latina se gobierna como un pequeño municipio romano, y los que son sus magistrados se hacen ciudadanos romanos al acabar su año de cargo, con sus padres, su mujer y sus hijos. Así, poco a poco, las mejores familias de Hispania entran en la ciudadanía.'],['¿Cómo es la ley de Malaca?','Está grabada en grandes tablas de bronce, expuestas en el foro: cómo se eligen los magistrados, cuántos votos hacen falta, qué juramentos prestan, cuánto puede gastar el edil en juegos. Los arqueólogos encontrarán tablas como esta en Málaga, en el siglo XIX, y otras en un lugar llamado Irni, en el XX.'],['¿Podría yo ser magistrado?','Tendrías que ser munícipe, miembro de pleno derecho de la ciudad. Un forastero puede ser admitido si los decuriones lo aceptan y demuestra que tiene medios. Luego tienes que presentarte a edil, hacer campaña, jurar la ley y pagar parte de los juegos. Al acabar el año, ciudadano romano. Es largo, pero es el camino de los hispanos.']],
 quiz:{q:'¿Qué recibían los magistrados de un municipio latino al terminar su cargo?',a:['La ciudadanía romana, para ellos y su familia','Un sueldo de por vida','Un asiento en el Senado de Roma'],ko:'No. Al terminar su cargo, los magistrados de un municipio latino recibían la ciudadanía romana, ellos y su familia.'}};
ROMA_DEST_NPCS.push(MALACITANO);
Object.assign(ROMA_DEST_SRC,{malacitano:{a:['Plinio, Historia natural III 30 (el derecho latino de Hispania)','Ley Flavia municipal: tablas de Malaca y Salpensa (CIL II 1963-1964) e Irni (1981), capítulos 21-23 (la ciudadanía por la magistratura)','Suetonio, Claudio 15 (la toga)'],m:['J. González, «The Lex Irnitana», Journal of Roman Studies 76 (1986)'],n:['Lucio Valerio Firmo es inventado. En el juego, el camino a la magistratura está muy simplificado.']}});
Object.assign(ROMA_SRC,{paisano:{a:['Plinio, Historia natural III 30 y XVI 236 (las estaciones de los municipios)','Suetonio, Claudio 15 y Vespasiano 8 (la toga; la libertad de Acaya)','Tácito, Agrícola 4 y 21','Horacio, Epístolas II 1.156'],m:['A. N. Sherwin-White, The Roman Citizenship (1973)'],n:['Los paisanos son inventados.']}});
// la patria al elegir el personaje
function fxOrigSelect(){const L=ORIG[MODE]||[],p=pjz(),f=state&&state.fx,lock=!!(f&&(f.st==='meteco'||f.ciu));return '<select id="pjOrig"'+(lock?' disabled title="Ya no puedes cambiar de patria"':'')+' style="font:inherit;padding:4px 8px">'+L.map(o=>'<option value="'+o.id+'"'+(p&&p.o===o.id?' selected':'')+'>'+o.n+'</option>').join('')+'</select>';}
function fxSetOrig(id){const p=pjz();if(!p)return;p.o=id;save();fxRelabel();}
function fxRelabel(){const ob=npcObjs.find(o=>o.data===PAISANO);if(!ob)return;const vis=ob.lb.visible;ob.g.remove(ob.lb);const lb=labelSprite(PAISANO.name,PAISANO.title,true);lb.position.y=2.45;lb.visible=vis;ob.g.add(lb);ob.lb=lb;}
// opciones extra en las conversaciones
function fxOpts(n,add){const f=fxz(),o=origen(),ro=MODE==='roma';
  if(n.id==='paisano'&&o){
    if(!ro&&f.st==='xenos')add(f.prost?'Ya tengo prostátes: ¿y ahora?':'Quiero quedarme a vivir en Atenas','quiz',()=>{if(!f.prost){f.prost=true;save();}
      $('dBody').innerHTML='<p>'+(o.barb||o.id==='naucratis'?'«Hecho: un ciudadano ateniense responderá por ti. ':'«Yo mismo seré tu prostátes: respondo por ti ante la ciudad. ')+'Ahora ve a la mesa del demarco de Mélite, aquí en el Ágora, y paga el metoíkion: '+(pjFem()?'seis dracmas, treinta y seis óbolos, porque eres una mujer que vive por su cuenta':'doce dracmas, setenta y dos óbolos')+'. Y no tardes: a quien vive aquí sin inscribirse lo puede denunciar cualquiera, y la pena es ser vendido como esclavo».</p>';renderOpts();});
    if(ro&&!f.ciu)add('¿Cómo puedo hacerme ciudadano romano?','quiz',()=>{$('dBody').innerHTML='<p>'+o.tp[o.id==='malaca'?1:2][1]+'</p><p class="sub">Pista: el duunviro de Malaca está en Corduba (viaja por mar a Tarraco y por tierra hasta Corduba).</p>';renderOpts();});
    if(fxNostosOk())add(f.nostos?'Sobre mi regreso…':'He pensado en volver a casa','quiz',()=>fxNostos(n));}
  if(n.id==='demarco'&&f.st==='xenos'){const fee=pjFem()?36:72;
    add('Inscribirme como meteco ('+fee+' óbolos)','quiz',()=>{const B=$('dBody');
      if(!o){B.innerHTML='<p>«Primero dime de dónde eres». (Elige tu patria en el Diario, pestaña «Forastero».)</p>';renderOpts();return;}
      if(!f.prost){B.innerHTML='<p>«¿Y quién responde por ti? Sin prostátes no te puedo inscribir. Busca a tu próxeno o a alguien de tu tierra: está cerca, junto a Lisias».</p>';renderOpts();return;}
      if(state.obols<fee){B.innerHTML='<p>«Te faltan '+(fee-state.obols)+' óbolos. Vuelve cuando los tengas, pero no tardes mucho».</p>';renderOpts();return;}
      state.obols-=fee;f.st='meteco';f.dm=state.day||1;save();updateStats();sfxCoin();qAdd('kl',2);
      B.innerHTML='<p>Nausícrates moja el cálamo y escribe en la lista: «'+pjz().name+', '+(o.de)+', residente en Mélite». Luego cuenta tus óbolos dos veces.</p><p>«Ya eres '+fxG('meteco','meteca')+'. No votarás, pero nadie podrá echarte. Y el año que viene, otra vez el metoíkion: no lo olvides».</p>';
      toast('<span class="label">Ya eres '+fxG('meteco','meteca')+'</span><br>'+pjz().name+' '+o.de+', residente en Mélite.');renderOpts();});}
  if(n.id==='malacitano'&&!f.ciu&&pjFem())add('¿Puedo presentarme a magistrada?','quiz',()=>{$('dBody').innerHTML='<p>«¿Magistrada? Las mujeres no pueden ser magistradas, ni aquí ni en Roma. Una mujer de Malaca se hace ciudadana romana con su padre o su marido cuando ellos lo son, o por concesión del emperador».</p><p class="sub">En tu Diario (pestaña «Forastero») tienes los caminos posibles.</p>';renderOpts();});
  if(n.id==='malacitano'&&!f.ciu&&!pjFem()){const fee=200;
    add('Pedir ser admitido como munícipe y presentarme a edil ('+fee+' sestercios)','quiz',()=>{const B=$('dBody');
      if(state.obols<fee){B.innerHTML='<p>«Un edil paga de su bolsa parte de los juegos y regala algo a la ciudad. Sin '+fee+' sestercios, los decuriones no te tomarán en serio. Te faltan '+(fee-state.obols)+'».</p>';renderOpts();return;}
      state.obols-=fee;f.ciu=true;f.via='municipio';f.dc=state.day||1;save();updateStats();sfxCoin();qAdd('kl',5);pjAvatar();
      const c=cz();if(c.st<2){c.st=2;c.fr=c.fr||'derecho latino';save();}
      B.innerHTML='<p>Los decuriones de Malaca te admiten como munícipe. En los comicios del año siguiente te eligen edil: vigilas el mercado, los pesos y las medidas, las calles y los baños, y pagas tu parte de los juegos. Al terminar tu año juras ante el foro, junto a la ley de bronce.</p><p>«Desde hoy eres '+fxG('ciudadano romano','ciudadana romana')+', con tus padres y tus hijos. Como todos los nuevos ciudadanos de los municipios flavios, tomas el nombre de familia del emperador: '+(pjFem()?'Flavia':'Tito Flavio')+' '+pjz().name+'. ¡Ya puedes llevar '+(pjFem()?'la estola de matrona':'la toga')+'!».</p><p class="sub">En el juego todo ocurre en un momento: en realidad eran, como poco, uno o dos años.</p>';
      toast('<span class="label">Ciudadanía romana</span><br>Ahora eres '+fxNombre()+'.');renderOpts();});}
  // hospitalidad en los destinos
  const ob=npcObjs.find(x=>x.data===n),I=ob&&islandOf(ob.x);
  if(I&&!f.tes[I.id]&&n.id!=='paisano')add(ro?'Pedir hospitalidad (hospitium)':'Pedir hospitalidad (xenía)','quiz',()=>{f.tes[I.id]={who:n.name,d:state.day||1};save();sfxCoin();qAdd('kl',1);
    $('dBody').innerHTML=ro?'<p>'+n.name+' te ofrece su casa y su mesa. Antes de despedirse, os dais la mano y te entrega una tésera de hospitalidad: una pequeña placa de bronce con dos manos estrechadas y vuestros nombres. Él guarda otra igual. Quien la presente, o sus hijos, será recibido como un amigo. En Hispania se han encontrado muchas téseras así, en forma de manos o de animales.</p><p class="sub">Desde '+I.name+', tu anfitrión te consigue pasajes a mitad de precio.</p>':'<p>'+n.name+' te acoge en su casa: «Zeus Xenio protege a los forasteros». Antes de irte, parte por la mitad una tablilla con su sello y te da un trozo: es un sýmbolon. Si algún día vuelves tú, o alguien de tu familia, con esa mitad, las piezas encajarán y será recibido como un hermano. Así lo hacían Glauco y Diomedes en la Ilíada: amigos por sus abuelos, aunque luchaban en bandos contrarios.</p><p class="sub">Desde '+I.name+', tu anfitrión te consigue pasajes a mitad de precio.</p>';
    toast('<span class="label">'+(ro?'Tésera de hospitalidad':'Sýmbolon de hospitalidad')+'</span><br>'+n.name+', en '+I.name+'.');renderOpts();});
  // «¿y en tu tierra?»
  const C=(FX_COMPARA[MODE]||{})[n.id];if(C&&!f.cuad[n.id])add('«¿Y en tu tierra cómo es?»','quiz',()=>fxCompara(n,C));
}
// cuaderno de comparaciones
const FX_COMPARA={
 atenas:{
  nodriza:{q:'¿Cómo se celebra en tu tierra que nace un niño?',x:'Aquí, al quinto día, el padre lo lleva corriendo alrededor del hogar, y al décimo le ponemos nombre, casi siempre el del abuelo. ¿Y allí de donde vienes?'},
  aristofanes:{q:'¿De qué se ríe la gente en tu tierra?',x:'En Atenas nos reímos de los poderosos en el teatro, con nombre y apellido: de Cleón, de Sócrates, de los generales. ¿En tu tierra se puede hacer eso?'},
  sacerdotisa:{q:'¿A qué dioses rezáis en tu tierra, y cómo?',x:'Aquí honramos a los dioses con sacrificios: la grasa y los huesos para ellos, la carne para el banquete de todos. ¿Cómo lo hacéis vosotros?'},
  hoplita:{q:'¿Quién defiende tu ciudad?',x:'En Atenas, cada ciudadano se paga su escudo y su lanza y forma en la falange; los pobres reman en las trirremes. ¿Quién lucha en tu tierra?'},
  lisias:{q:'¿Cómo trata tu tierra a los extranjeros que viven en ella?',x:'Aquí los metecos pagamos un impuesto por no ser de aquí, no votamos y no podemos tener tierra. A cambio, nos dejan trabajar en paz. ¿Y en tu tierra?'},
  pritano:{q:'¿Quién decide las leyes en tu tierra?',x:'Aquí las decide la Asamblea: cualquier ciudadano varón puede hablar y votar, y muchos cargos se sortean. ¿Quién manda allí de donde vienes?'}},
 roma:{
  quintiliano:{q:'¿Cómo aprenden los niños en tu tierra?',x:'Yo digo que hay que enseñar con paciencia y alabanzas, no a golpes, aunque muchos maestros no me hacen caso. ¿Cómo se enseña en tu tierra?'},
  pomponia:{q:'¿Cómo os casáis en tu tierra?',x:'Aquí la novia lleva velo color de fuego, se unen las manos derechas y la llevan en brazos para cruzar el umbral. ¿Cómo es una boda en tu tierra?'},
  josefo:{q:'¿Qué costumbres de tu pueblo defenderías ante extranjeros que se burlan?',x:'He escrito para que los romanos entiendan las costumbres de mi pueblo: el sábado, la Ley, la comida. Muchos se ríen de lo que no conocen. ¿Qué costumbres de tu tierra defenderías?'},
  medico:{q:'¿Cómo se curan los enfermos en tu tierra?',x:'Los romanos desconfían de los médicos griegos como yo: prefieren las recetas de la abuela y los dioses. ¿A quién acudís en tu tierra cuando alguien enferma?'},
  marcial:{q:'¿Qué se come en tu tierra en una cena de fiesta?',x:'En Roma, en una buena cena hay huevos, pescado, lirón relleno y vino de Falerno, y alguien recita versos. ¿Qué se come en tu tierra cuando hay fiesta?'},
  musonio:{q:'¿Estudian filosofía las mujeres en tu tierra?',x:'Yo enseño que las mujeres deben estudiar filosofía igual que los hombres, porque tienen la misma razón y la misma virtud. Muchos se ríen. ¿Y en tu tierra?'}}};
function fxCompara(n,C){const B=$('dBody'),o=$('dOpts');B.innerHTML='<p>«'+C.x+'»</p><p><textarea id="fxAns" maxlength="400" rows="3" style="width:100%;font:inherit;padding:6px" placeholder="Escribe tu respuesta: se guardará en tu cuaderno de viaje (Diario, pestaña «Forastero»)"></textarea></p>';
  o.innerHTML='';let k=1;const add=(t,fn)=>{const b=document.createElement('button');b.innerHTML='<span class="n">'+(k++)+'</span><span>'+t+'</span>';b.onclick=fn;o.appendChild(b);};
  const ta=$('fxAns');ta.addEventListener('keydown',e=>e.stopPropagation());setTimeout(()=>ta.focus(),40);
  add('Guardar en mi cuaderno',()=>{const a=(ta.value||'').replace(/[<>&]/g,'').trim();if(!a){ta.focus();return;}const f=fxz();f.cuad[n.id]={who:n.name,q:C.q,a,d:state.day||1};save();qAdd('kl',1);
    B.innerHTML='<p>'+n.name+' te escucha con atención. «Qué curioso. Nunca lo había pensado así».</p><p class="sub">Heródoto cuenta que el rey Darío preguntó a unos griegos por cuánto dinero se comerían a sus padres muertos, y dijeron que por nada del mundo; luego preguntó a los calatios, que sí se los comían, por cuánto los quemarían, y gritaron horrorizados. Y concluye con Píndaro: «la costumbre es la reina de todo» (Historias III 38).</p>';renderOpts();});
  add('Prefiero no contestar',()=>{$('dBody').innerHTML='<p>«Como quieras. Otro día me lo cuentas».</p>';renderOpts();});}
// el regreso
function fxNostosOk(){const f=fxz();return state.lessons.length>=12||f.st==='meteco'||f.ciu;}
function fxNostos(n){const f=fxz(),o=origen(),ro=MODE==='roma',B=$('dBody'),O=$('dOpts');const nt=Object.keys(f.tes).length,nc=Object.keys(f.cuad).length;
  O.innerHTML='';let k=1;const add=(t,fn)=>{const b=document.createElement('button');b.innerHTML='<span class="n">'+(k++)+'</span><span>'+t+'</span>';b.onclick=fn;O.appendChild(b);};
  if(f.nostos){B.innerHTML='<p>'+fxEpi(f.nostos)+'</p>';add('Volver a la conversación',()=>{$('dBody').innerHTML='<p>Pregunta lo que quieras.</p>';renderOpts();});return;}
  B.innerHTML='<p>«Nóstos, el regreso. Ulises tardó diez años en volver a Ítaca, y cuando llegó nadie lo reconoció, salvo su perro. ¿Quieres volver '+o.de.replace(/^de /,'a ')+' o quedarte '+(ro?'en Roma':'en Atenas')+'? Piénsalo: los que se van nunca vuelven siendo los mismos».</p><p class="sub">Has aprendido '+state.lessons.length+' lecciones, tienes '+nt+' '+(nt===1?'anfitrión':'anfitriones')+' y '+nc+' '+(nc===1?'respuesta':'respuestas')+' en tu cuaderno. Puedes seguir jugando decidas lo que decidas.</p>';
  add('Volver a mi tierra',()=>{f.nostos='volver';save();B.innerHTML='<p>'+fxEpi('volver')+'</p>';toast('<span class="label">Nóstos</span><br>Has elegido volver.');O.innerHTML='';add('Seguir explorando',()=>{$('dBody').innerHTML='<p>Pregunta lo que quieras.</p>';renderOpts();});});
  add('Quedarme aquí',()=>{f.nostos='quedarse';save();B.innerHTML='<p>'+fxEpi('quedarse')+'</p>';toast('<span class="label">Nóstos</span><br>Has elegido quedarte.');O.innerHTML='';add('Seguir explorando',()=>{$('dBody').innerHTML='<p>Pregunta lo que quieras.</p>';renderOpts();});});
  add('Todavía no lo sé',()=>{$('dBody').innerHTML='<p>«No hay prisa. Ulises tampoco la tuvo».</p>';renderOpts();});}
function fxEpi(k){const f=fxz(),o=origen(),ro=MODE==='roma',nt=Object.keys(f.tes).length,nm=fxNombre(),home=o?o.n.split(',')[0]:'tu tierra';
  if(k==='volver')return 'Al cabo de unas semanas, '+nm+' desembarca en '+home+'. Los vecinos no paran de preguntar: '+(ro?'cómo es el Anfiteatro, si es verdad que Roma tiene un millón de habitantes, cómo habla el emperador':'cómo es el Partenón, si es verdad que en Atenas cualquiera habla en la Asamblea, qué se ríe en el teatro')+'. '+(nt?'Guardas en un cofre '+nt+' '+(ro?(nt===1?'tésera':'téseras'):(nt===1?'sýmbolon':'sýmbola'))+' de hospitalidad: si algún día tus hijos viajan, tendrán dónde dormir. ':'')+(ro&&f.ciu?'En el foro de tu ciudad te miran con respeto: eres '+fxG('ciudadano romano y llevas la toga','ciudadana romana y llevas la estola de matrona')+'. ':'')+(!ro&&f.st==='meteco'?'Durante un tiempo, los tuyos te llaman '+fxG('«el ateniense»','«la ateniense»')+', medio en broma. ':'')+'Como Ulises, vuelves siendo otro: ahora sabes que cada pueblo cree que sus costumbres son las mejores.';
  return nm+' se queda. '+(ro?(f.ciu?'Como '+fxG('ciudadano romano','ciudadana romana')+', con tu casa y tus amigos, Roma ya es tu patria, aunque tu acento te delate siempre. ':'Sigues siendo '+fxG('peregrino','peregrina')+', pero Roma está llena de gente como tú: casi la mitad de la ciudad ha nacido fuera. '):(f.st==='meteco'?'Como '+fxG('meteco','meteca')+', pagarás cada año el metoíkion y nunca votarás, pero tus hijos crecerán en Atenas. Algunos metecos, como Pasión el banquero, acaban recibiendo la ciudadanía por sus servicios. ':'Pero tendrás que inscribirte como meteco: nadie puede quedarse en Atenas para siempre sin hacerlo. '))+'De vez en cuando, en el puerto, preguntas a los marineros por '+home+'.';}
// llegadas, cambistas, la xenelasía de Esparta y el aviso del meteco
const FX_COINS={egina:'las «tortugas» de plata de Egina, más pesadas que las monedas áticas',corinto:'los «potros» de Corinto, con Pegaso',tebas:'las monedas beocias, con un escudo',esparta:'¡ninguna! En Esparta los ciudadanos usan barras de hierro y te miran mal si sacas plata',argos:'las monedas de Argos, con media loba',efeso:'las monedas de Éfeso, con una abeja',mileto:'las monedas de Mileto, con un león',sardes:'los dáricos de oro del Gran Rey, con un arquero',creta:'las monedas de Cnosos, con el laberinto',olimpia:'las monedas de Élide, con el águila de Zeus',delfos:'las monedas de Delfos, con una cabeza de carnero',naxos:'las monedas de Naxos, con una copa de Dioniso'};
function fxArrive(to){if(MODE!=='atenas')return;const f=fxz(),c=FX_COINS[to];if(!c||f.coins[to])return;f.coins[to]=1;let fee='';if(state.obols>=1){state.obols-=1;fee=' Te cobra un óbolo por cambiarte el dinero.';updateStats();}save();
  setTimeout(()=>toast('<span class="label">El cambista</span><br>Aquí usan '+c+'. Cada ciudad acuña su propia moneda; las lechuzas de Atenas se aceptan casi en todas partes, pero no siempre al mismo precio.'+fee),1200);}
const FXT={sp:0,warnSp:false,last:0,pnyx:false};
function fxTick(dt){if(ui!=='play'||!state)return;const f=fxz();
  if(MODE==='atenas'){const I=islandOf(player.x);
    if(I&&I.id==='esparta'){FXT.sp+=dt;if(FXT.sp>150&&!FXT.warnSp){FXT.warnSp=true;toast('<span class="label">Esparta</span><br>Un espartano se te acerca: «Forastero, los éforos preguntan qué haces aquí tanto tiempo». En Esparta, los extranjeros son expulsados de vez en cuando: la xenelasía.');}
      if(FXT.sp>300){FXT.sp=0;FXT.warnSp=false;const P=PORTS.esparta;if(P){player.x=P.x;player.z=P.z;player.feet=floorAt(P.x,P.z);player.camY=player.feet+player.eye;player.yaw=P.yaw;}toast('<span class="label">Xenelasía</span><br>Dos espartanos te acompañan, muy educados y muy firmes, hasta el camino de salida. Tucídides cuenta que Pericles presumía de que Atenas, en cambio, no expulsaba a los extranjeros.');}}
    else{FXT.sp=0;FXT.warnSp=false;}
    if(f.st==='xenos'&&pjz()){const d=(state.day||1)-f.d0;if(d>=4&&f.warn!==1&&f.warn!==2){f.warn=1;save();toast('<span class="label">Forastero</span><br>Llevas ya varios días en Atenas. Si vas a quedarte, inscríbete como meteco: habla con tu próxeno (junto a Lisias, en el Ágora) y con el demarco de Mélite.');}
      if(d>=10&&f.warn!==2){f.warn=2;save();toast('<span class="label">Un sicofanta</span><br>Un tipo con mala cara te sigue por el Ágora: «Un forastero sin prostátes… Podría denunciarte por aprostasíou, y te venderían como esclavo». Se ríe y se va. Mejor que te inscribas pronto.');}}}}
function fxZone(id){if(MODE==='atenas'&&id==='pnyx'&&!FXT.pnyx){FXT.pnyx=true;const f=fxz();setTimeout(()=>toast('<span class="label">La Pnyx</span><br>'+(f.st==='meteco'?'Como '+fxG('meteco','meteca'):'Como '+fxG('forastero','forastera'))+(pjFem()?' y como mujer':'')+', no puedes votar en la Asamblea: solo los ciudadanos varones adultos. Puedes mirar desde lejos, como tantos otros.'),1800);}}
// diario: pestaña «Forastero»
function fxJournal(){const f=fxz(),o=origen(),ro=MODE==='roma',p=pjz();let h='<p style="margin:0 0 12px;max-width:68ch;line-height:1.5">'+(ro?'En el Imperio, la mayoría de la gente libre no era ciudadana de Roma: eran peregrinos. Tú también lo eres, al menos de momento.':'En Atenas, quien no es ciudadano es un forastero (xénos) o, si se queda a vivir, un meteco. Tú también lo eres.')+'</p><div class="entries">';
  h+='<div class="entry"><span class="label">Tu patria</span><h3>'+(o?o.n:'Sin elegir')+'</h3><p>'+(p?'Te llamas '+fxNombre()+'. ':'')+'Patria: '+fxOrigSelect()+'</p><p class="sub">'+(o?'Tu paisano: '+o.pn+' ('+o.pt+'). ':'')+(ro?'Está en las estaciones de los municipios, junto al Templo de la Paz.':'Está en el Ágora, cerca de Lisias.')+'</p></div>';
  if(state.jero){jeroCSS();h+='<div class="entry"><span class="label">Tu nombre en jeroglíficos</span><h3>'+state.jero.n+'</h3><p style="text-align:center"><span class="cartucho">'+state.jero.g+(state.jero.f?'𓁐':'𓀀')+'</span></p><p class="sub">Escrito por un escriba de Egipto con los signos de un solo sonido.</p></div>';}
  const st=ro?(f.ciu?'<h3>'+fxG('Ciudadano romano','Ciudadana romana')+'</h3><p>Desde que fuiste edil en Malaca eres '+fxNombre()+'. Puedes llevar '+fxG('toga','la estola de matrona')+', casarte según el derecho romano, hacer testamento y comprar suelo romano.</p>':'<h3>'+fxG('Peregrino','Peregrina')+'</h3><p>No eres '+fxG('ciudadano romano','ciudadana romana')+': no puedes llevar toga ni comprar suelo romano. Caminos: el emperador (pide a un amigo importante que te recomiende; habla con el argentario Sexto Afranio) o el derecho latino de Hispania (busca al duunviro de Malaca en Corduba).</p>'):
    (f.st==='meteco'?'<h3>'+fxG('Meteco','Meteca')+', residente en Mélite</h3><p>Pagas el metoíkion cada año. No votas ni puedes tener casa sin un decreto de la Asamblea (pregunta a Formión, en la mesa de Pasión).</p>':'<h3>'+fxG('Forastero','Forastera')+' de paso</h3><p>Si te quedas, tienes que inscribirte como meteco: '+(f.prost?'ya tienes prostátes; ve al demarco de Mélite y paga el metoíkion.':'primero habla con tu próxeno para que responda por ti; luego, con el demarco de Mélite.')+'</p>');
  h+='<div class="entry"><span class="label">Tu situación</span>'+st+'</div>';
  const T=Object.entries(f.tes);h+='<div class="entry"><span class="label">'+(ro?'Téseras de hospitalidad':'Sýmbola de hospitalidad')+' · '+T.length+'</span><h3>Tus anfitriones</h3><p>'+(T.length?T.map(([d,t])=>{const I=destOf(d);return (I?I.name:d)+': '+t.who;}).join(' · '):'Todavía ninguno. En cada ciudad que visites, pide hospitalidad a alguien con quien hables: desde allí te conseguirá pasajes a mitad de precio.')+'</p></div>';
  const Cq=Object.values(f.cuad);h+='<div class="entry"><span class="label">Cuaderno de viaje · '+Cq.length+' de '+Object.keys(FX_COMPARA[MODE]||{}).length+'</span><h3>«¿Y en tu tierra cómo es?»</h3>'+(Cq.length?Cq.map(c=>'<p><b>'+c.q+'</b> <span class="sub">('+c.who+')</span><br>'+c.a+'</p>').join(''):'<p>Algunas personas te preguntarán por las costumbres de tu tierra. Tus respuestas se guardan aquí.</p>')+'<p style="margin-top:8px"><button class="linkbtn" id="fxEnt">Entregar mi cuaderno al profesor (descargar)</button> · <button class="linkbtn" id="fxCop">Copiar el texto</button></p></div>';
  h+='<div class="entry"><span class="label">Nóstos</span><h3>El regreso</h3><p>'+(f.nostos?fxEpi(f.nostos):fxNostosOk()?'Ya puedes decidir si vuelves a tu tierra o te quedas: habla con tu paisano.':'Cuando hayas vivido lo suficiente aquí (12 lecciones o tu inscripción '+(ro?'como ciudadano':'como meteco')+'), tu paisano te preguntará si quieres volver.')+'</p></div>';
  return h+'</div>';}

// ---- el cuaderno de viaje para el profesorado: el alumno lo entrega como archivo (Diario › Forastero) y el profesor abre los de toda la clase en su panel
function fxCuadData(){const out={juego:'mundo-clasico',tipo:'cuaderno',fecha:new Date().toISOString().slice(0,10),modos:[]};
  for(const[m,key]of[['atenas','atenas-386-v1'],['roma','roma-80-v1']]){let st=null;if(m===MODE)st=state;else try{st=JSON.parse(localStorage.getItem(key)||'null');}catch(e){}
    if(!st||!st.fx)continue;const f=st.fx,pj=st.pj||{},L=ORIG[m]||[],o=L.find(x=>x.id===pj.o);const fem=pj.g==='f';
    const est=m==='roma'?(f.ciu?(fem?'ciudadana romana':'ciudadano romano'):(fem?'peregrina':'peregrino')):(f.st==='meteco'?(fem?'meteca':'meteco'):(fem?'forastera':'forastero'));
    out.modos.push({modo:m,nombre:(m==='roma'&&f.ciu?(fem?'Flavia ':'Tito Flavio '):'')+(pj.name||'(sin nombre)'),patria:o?o.n:'(sin elegir)',estatus:est,lecciones:(st.lessons||[]).length,anfitriones:Object.keys(f.tes||{}).length,nostos:f.nostos||'',respuestas:Object.values(f.cuad||{}).map(c=>({who:c.who,q:c.q,a:c.a}))});}
  out.alumno=(out.modos[0]&&out.modos[0].nombre)||'(sin nombre)';return out;}
function fxCuadTxt(d){const ep=k=>k==='volver'?'ha decidido volver a su tierra':k==='quedarse'?'ha decidido quedarse':'aún no ha decidido si vuelve';
  let t='NÓSTOS · CUADERNO DE VIAJE\n'+d.alumno+' · '+d.fecha+'\n';
  for(const m of d.modos){t+='\n== '+(m.modo==='roma'?'Roma, 80 d.C.':'Atenas, 386 a.C.')+' ==\n'+m.nombre+', de '+m.patria+' · '+m.estatus+' · '+m.lecciones+' lecciones · '+m.anfitriones+' anfitriones · '+ep(m.nostos)+'\n';
    if(!m.respuestas.length)t+='(sin respuestas todavía)\n';m.respuestas.forEach((r,i)=>{t+='\n'+(i+1)+'. '+r.q+' ('+r.who+')\n   '+r.a+'\n';});}
  return t;}
function fxCuadFile(){const d=fxCuadData();return fxCuadTxt(d)+'\n---DATOS---\n'+JSON.stringify(d);}
function fxCuadName(){const n=(fxCuadData().alumno||'alumno').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^A-Za-z0-9]+/g,'_');return 'cuaderno_'+n+'.txt';}
function fxCuadParse(txt){try{const i=txt.indexOf('---DATOS---');const d=JSON.parse(i>=0?txt.slice(i+11):txt);if(d&&d.tipo==='cuaderno'&&Array.isArray(d.modos))return d;}catch(e){}return null;}
function fxCuadHTML(d){const esc=s=>String(s).replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]));let h='<div style="padding:8px 4px;border-bottom:1px solid #4a3a2c"><b style="color:#ecc29a">'+esc(d.alumno)+'</b> <span class="sub">· entregado el '+esc(d.fecha)+'</span>';
  for(const m of d.modos){h+='<div class="sub" style="margin-top:6px">'+(m.modo==='roma'?'Roma':'Atenas')+': '+esc(m.nombre)+', de '+esc(m.patria)+' · '+esc(m.estatus)+' · '+m.lecciones+' lecciones · '+m.anfitriones+' anfitriones'+(m.nostos?' · '+(m.nostos==='volver'?'vuelve a casa':'se queda'):'')+'</div>';
    h+=m.respuestas.length?m.respuestas.map(r=>'<p style="margin:6px 0 0"><i>'+esc(r.q)+'</i> <span class="sub">('+esc(r.who)+')</span><br>'+esc(r.a)+'</p>').join(''):'<p class="sub" style="margin:6px 0 0">Sin respuestas todavía.</p>';}
  return h+'</div>';}
const FXCLASE=[];
function fxProfeCuadernos(){const b=$('profe')&&$('profe').querySelector('.pb');if(!b)return;
  b.innerHTML='<h2>Cuadernos de viaje</h2><p class="sub">Cada alumno entrega su cuaderno desde el Diario, pestaña «Forastero» («Entregar mi cuaderno»): se descarga un archivo de texto. Ábrelos aquí todos a la vez para leerlos juntos, o pega el texto de uno.</p>'+
   '<div class="acts"><button id="fxcFile">Abrir archivos de alumnos…</button><button id="fxcPaste">Pegar un cuaderno</button><button id="fxcMine">Ver el de este navegador</button><button id="fxcAll">Descargar todos en un solo archivo</button><button id="fxcClr">Vaciar la lista</button><button id="fxcBack">Volver al panel</button></div>'+
   '<input id="fxcIn" type="file" accept=".txt,.json,text/plain,application/json" multiple hidden><textarea id="fxcTa" rows="3" hidden placeholder="Pega aquí el texto completo del cuaderno y pulsa «Añadir»" style="width:100%;background:#14100c;color:#f1e8d8;border:1px solid #6a5040;font:inherit"></textarea><div class="acts"><button id="fxcAdd" hidden>Añadir</button></div><div class="list" id="fxcL"></div>';
  const L=$('fxcL'),draw=()=>{L.innerHTML=FXCLASE.length?FXCLASE.map(fxCuadHTML).join(''):'<p class="sub" style="padding:8px">Todavía no has abierto ningún cuaderno.</p>';};
  const addD=d=>{const i=FXCLASE.findIndex(x=>x.alumno===d.alumno&&x.fecha===d.fecha);if(i>=0)FXCLASE[i]=d;else FXCLASE.push(d);FXCLASE.sort((a,b)=>a.alumno.localeCompare(b.alumno));draw();};
  $('fxcFile').onclick=()=>$('fxcIn').click();
  $('fxcIn').onchange=e=>{let bad=0;const fs=[...e.target.files];let n=fs.length;fs.forEach(f=>{const r=new FileReader();r.onload=()=>{const d=fxCuadParse(String(r.result));if(d)addD(d);else bad++;if(--n===0&&bad)toast(bad+' archivo'+(bad>1?'s no son cuadernos':' no es un cuaderno')+' de Nóstos.');};r.readAsText(f);});e.target.value='';};
  $('fxcPaste').onclick=()=>{$('fxcTa').hidden=false;$('fxcAdd').hidden=false;$('fxcTa').focus();};
  $('fxcTa').addEventListener('keydown',e=>e.stopPropagation());
  $('fxcAdd').onclick=()=>{const d=fxCuadParse($('fxcTa').value);if(!d){toast('Ese texto no es un cuaderno de Nóstos: pega el archivo completo, con la parte «---DATOS---».');return;}addD(d);$('fxcTa').value='';};
  $('fxcMine').onclick=()=>addD(fxCuadData());
  $('fxcAll').onclick=()=>{if(!FXCLASE.length){toast('No hay cuadernos abiertos.');return;}offerDownload('cuadernos_de_la_clase.txt',FXCLASE.map(fxCuadTxt).join('\n\n------------------------------------------------\n\n'));};
  $('fxcClr').onclick=()=>{FXCLASE.length=0;draw();};$('fxcBack').onclick=()=>{profeClose();profeOpen();};
  draw();}
function fxEntregar(){offerDownload(fxCuadName(),fxCuadFile());}

